  param($directory,$hashes);$ErrorActionPreference='Stop';foreach($name in $hashes.Keys){if((Get-FileHash -LiteralPath (Join-Path $directory $name)).Hash -cne $hashes[$name]){throw 'Transferred source differs'}};foreach($source in @('windows-dns-credential-recovery.ps1','windows-recovery-envelope.ps1')){. (Join-Path $directory $source)}
  function Config([string]$token){return @{apiVersion='v1';kind='Config';clusters=@(@{name='cluster';cluster=@{server='https://10.99.15.50:6443';'tls-server-name'='kubernetes.cormierconsulting.io';'certificate-authority-data'='Synthetic-Pinned-CA'}});users=@(@{name='bridge';user=@{token=$token}});contexts=@(@{name='bridge';context=@{cluster='cluster';user='bridge';namespace='dns-system'}});'current-context'='bridge'}|ConvertTo-Json -Depth 10 -Compress}
