 };$public|Set-Content -LiteralPath $taskPublicFile;& node (Join-Path $taskRoot 'scripts/prepare-windows-recovery-channel-test.mjs') $taskPublicFile $taskFixtureFile;if($LASTEXITCODE -ne 0){throw 'Encrypted channel fixtures failed'};Copy-Item -LiteralPath $taskFixtureFile -Destination ($taskDirectory+'\fixtures.json') -ToSession $taskSession
 $taskLedger.testIntent=[DateTime]::UtcNow.ToString('o');Save-ChannelReceipt;$result=Invoke-Command -Session $taskSession -ArgumentList $taskDirectory -ScriptBlock {param($directory);& (Join-Path $directory 'test.ps1') -Directory $directory};$taskLedger.results=($result|Out-String|ConvertFrom-Json);if(!$taskLedger.results.passed){throw 'Windows channel acceptance failed'};$taskLedger.passed=$true;$taskLedger.status='Verified; cleanup pending';Save-ChannelReceipt
